SELECT EXISTS (
    SELECT 1 FROM move_request
    WHERE id = #{moveRequestId, jdbcType=OTHER}
      AND customer_id = #{customerId, jdbcType=OTHER}
)

SELECT EXISTS (
    SELECT 1
    FROM move_request mr
    WHERE mr.id = #{moveRequestId, jdbcType=OTHER}
      AND (
        mr.customer_id = #{userId, jdbcType=OTHER}
        OR EXISTS (
            SELECT 1
            FROM reservation r
            JOIN technician_assignment ta ON ta.reservation_id = r.id
            JOIN technician_profile tp ON tp.id = ta.technician_id
            WHERE r.move_request_id = mr.id
              AND tp.user_id = #{userId, jdbcType=OTHER}
              AND tp.active = true
              AND tp.approval_status = 'APPROVED'
              AND ta.status IN (
                  'PENDING', 'ACCEPTED', 'ON_THE_WAY',
                  'WORK_STARTED', 'WORK_COMPLETED'
              )
        )
      )
)

SELECT EXISTS (
    SELECT 1 FROM move_request WHERE id = #{moveRequestId, jdbcType=OTHER}
)

SELECT EXISTS (
    SELECT 1 FROM move_item
    WHERE id = #{moveItemId, jdbcType=OTHER}
      AND move_request_id = #{moveRequestId, jdbcType=OTHER}
)

SELECT object_key, original_filename, content_type
FROM request_image
WHERE id = #{imageId, jdbcType=OTHER}
  AND move_request_id = #{moveRequestId, jdbcType=OTHER}
  AND purpose IN ('APPLIANCE', 'INSTALLATION_ENV')
